const fs = require('fs');

const D = parseInt(fs.readFileSync(0, 'utf8').trim(), 10);

// A partícula gasta 3 km do emissor até a entrada do acelerador.
// Dentro do acelerador (circunferência de 8 km), as saídas para os sensores
// estão nos marcos de 3, 4 e 5 km a partir do ponto de entrada:
//   3 km -> sensor 1, 4 km -> sensor 2, 5 km -> sensor 3
const m = (D - 3) % 8;

let sensor;
if (m === 3) sensor = 1;
else if (m === 4) sensor = 2;
else sensor = 3;

console.log(sensor);
